mapper.select:
	SELECT
	    COUNT(1) AS CNT 
	FROM
	    S02M043T 
	    INNER JOIN S02V001T 
	        ON S02M043T.APKIHONCD = S02V001T.APKIHONCD 
	        AND S02M043T.SHOPCD = S02V001T.SHOPCD 
	        AND S02M043T.SHNCD = S02V001T.SHNCD 
	        AND S02V001T.SHNZOKUSEI = #{shnzokusei,jdbcType=VARCHAR}  
	WHERE
	    S02M043T.APKIHONCD = #{apkihoncd,jdbcType=VARCHAR}  
	    AND S02M043T.SHOPCD = #{shopcd,jdbcType=VARCHAR}  
	    AND S02M043T.SHNCD = #{shncd,jdbcType=VARCHAR}  
	    AND S02M043T.YUKOKBN = #{yukokbn,jdbcType=VARCHAR}
